import{zc as e}from"./index-BZuUy872.js";import{t}from"./feature-matrix-C4H4yzHC.js";var n=[{name:`Architecture`,features:[{title:`Adapter pattern`,description:"Single `DataGridAdapter<TRow, TWhere>` interface — swap REST / GraphQL / Prisma / in-memory by implementing `load(query)`. Mutators (`updateRow / deleteRow / duplicateRow / bulkUpdate / bulkDelete`) are all optional.",status:`live`},{title:`Capability auto-detection`,description:"`inspectCapabilities(adapter)` derives a `{ updateRow, deleteRow, … }` boolean map. Plug-in features hide their UI for unimplemented mutators.",status:`live`},{title:`Two-provider composition`,description:"`<DataGridProvider>` runs the adapter; `<DataGridUIProvider>` holds search / filters / sort / pagination / selection / columns / density. Both required; clean separation of data vs. UI state.",status:`live`},{title:`Identity helpers`,description:"`defineColumns<TRow>()` / `defineFilterFields<TWhere>()` / `defineSortOptions<TFieldId>()` preserve literal types — column ids, filter ids, sort field ids autocomplete everywhere.",status:`live`},{title:`In-memory reference adapter`,description:"`createInMemoryAdapter` applies search / filters / sort / cursor pagination over a JS array. Use for prototyping or as a pattern reference for real adapters.",status:`live`}]},{name:`Filters`,features:[{title:`Filter picker`,description:`Two-stage popover: searchable + grouped field list, then a value editor per type. Arrow-key nav across both stages.`,status:`live`,shortcut:`f`},{title:`Editable filter pills`,description:`Each active filter renders as a pill with field · operator · value. Click to re-edit; × to remove.`,status:`live`},{title:`Text filter`,description:`Operators: contains / not contains / eq / neq / starts with / ends with / is empty / is not empty.`,status:`live`},{title:`Number filter`,description:`Operators: eq / neq / gt / gte / lt / lte / between / is empty / is not empty.`,status:`live`},{title:`Boolean filter`,description:`True / False with T/Y and F/N hotkeys for instant commit.`,status:`live`},{title:`Select filter`,description:"Single (`eq` / `neq`) or multi (`in` / `notIn`) — operator decides the picker shape. Search auto-shows when 4+ options.",status:`live`},{title:`Multi-select filter`,description:`Checkbox list for IN / NOT IN. Space toggles, Enter applies, search input never traps spaces.`,status:`live`},{title:`Date filter`,description:'The pickers kit `Calendar` in a popover; the value is the picked day\'s local midnight as an ISO timestamp. Operators: eq ("is", the whole calendar day: the in-memory adapter matches the day range and `dayBounds(value)` gives a `toWhere` the same inclusive range) / gt / gte / lt / lte. New filters start on gte.',status:`live`},{title:`Date-range filter`,description:`Two-month calendar with a sidebar of 7 presets (Today / Yesterday / Last 7d / Last 30d / MTD / QTD / YTD). Click a preset to commit instantly.`,status:`live`},{title:`Relation filter`,description:"Server-side debounced combobox via `loadOptions(query)`. Caches per query, dedupes in-flight requests, persists labels for URL roundtrips.",status:`live`},{title:`Relation multi filter`,description:`Same combobox, multi-pick mode. Stacks values into an IN clause.`,status:`live`},{title:`buildWhere engine`,description:"Merges every field's `toWhere(condition)` partial into a single `TWhere`. Bridges loose `FilterCondition` to the field's typed condition union — single cast at the engine boundary.",status:`live`},{title:`Operator allowlist per field`,description:"Each field can override its allowed operators via `operators?: FilterOperator[]`. Smart-default operator picked when adding a new filter.",status:`live`}]},{name:`Search`,features:[{title:`Always-on search input`,description:"Adapter declares `search: { placeholder, toWhere }` → `<DataGridSearch>` renders. 300ms debounce, clear button, `/` shortcut hint.",status:`live`,shortcut:`/`},{title:`Search-to-where translator`,description:"`search.toWhere(query)` returns a `Partial<TWhere>` merged with filters. Adapters implement free-text however they want (LIKE, full-text, embeddings).",status:`live`}]},{name:`Sort`,features:[{title:`Multi-rule sort`,description:`Stack arbitrary number of sort keys. Trigger label shows primary + arrow + "+N" badge.`,status:`live`,shortcut:`s`},{title:`Drag-reorder sort priority`,description:`GripVertical handle on every active rule — grab and drop to rerank. Up/down chevrons also work.`,status:`live`},{title:`Per-rule asc/desc toggle`,description:`Click the ↑/↓ icon on any rule to flip direction without losing priority.`,status:`live`},{title:`Header-click sort`,description:`Click a sortable header → asc → desc → cleared. Works alongside the dropdown.`,status:`live`},{title:`Add asc OR desc directly`,description:`Each available field shows ↑ / ↓ icons in the dropdown — click either to add a rule pre-set to that direction.`,status:`live`},{title:`Clear all`,description:`Appears when ≥ 2 active rules. One click resets sort.`,status:`live`}]},{name:`Columns`,features:[{title:`Custom cell renderers`,description:"`cell: (row, idx) => ReactNode`. Compose freely — avatars, badges, sparklines, anything.",status:`live`},{title:`Column visibility`,description:"Dropdown toggles columns on/off. Honors `meta.hideable: false` for non-hideable action columns.",status:`live`,shortcut:`c`},{title:`Drag-to-resize`,description:"Drag the right edge of any header. Min 40px. Per-column override stored in `useDataGridUI().columnSizes`.",status:`live`},{title:`Drag-to-reorder`,description:`Grab any header and drop on another to rearrange. Visual primary-line drop indicator.`,status:`live`},{title:`Header sort affordance`,description:`Sortable columns show ↕ / ↑ / ↓ chevron next to the header label.`,status:`live`},{title:`Per-column align / className`,description:'Override alignment + arbitrary className on header AND body cells via `meta`. `align: "start" | "end"` follow the reading direction (`end` for numbers); `"left" | "right"` stay physical.',status:`live`},{title:`Per-column header menu`,description:"Chevron on each header → Sort asc / Sort desc / Clear sort / Filter… / Hide column. Filter… opens the picker pre-seeded with the column's `meta.filterFieldId`. Hover-only so headers stay clean.",status:`live`},{title:`Pinned columns (start/end, left/right)`,description:'`meta.pin: "start" | "end"` (follow the reading direction: under `dir="rtl"` a start column sticks to the right edge, with its edge shadow mirrored) or the physical `"left" | "right"` — column stays visible while horizontally scrolling. Cumulative offsets computed automatically. Subtle gradient + inset border on the boundary cell. Pinned cols opt out of drag-reorder.',status:`live`},{title:`Column-level permissions`,description:'`meta.canRead(row)` → render placeholder ("—") instead of value. `meta.canEdit(row)` → fall back to read-only even when adapter has `updateRow`. Both row-context aware; distinct from hidden.',status:`live`},{title:`Auto-resize columns (fit-to-content)`,description:"Double-click a column's resize edge to fit it to its widest visible cell (Excel / Notion shape). Toolbar action \"Auto-fit all columns\" to size every visible column at once. Computed against the current page's rendered DOM; respects `meta.minSize` / `meta.maxSize`. Per-column override stored in `useDataGridUI().columnSizes` so the result survives next render.",status:`planned`},{title:`Multi-header column groups`,description:'`columnGroups` on `<DataGrid>` (MUI X\'s `columnGroupingModel` shape): `{ id, header, children: (columnId | group)[], description?, className? }`, typed by `defineColumnGroups<typeof columns>()`. `columns` stays flat, so order, visibility, sizes, pinning, saved views, CSV export and bulk edit are unchanged. One header row per nesting level; a group cell spans its visible, contiguous leaves and splits into one cell per run when a hidden or reordered column or a pin boundary cuts it; pinned groups stick with their leaves; ungrouped columns get an empty cell. `<th scope="colgroup">` (`columnheader` + `aria-colspan` in grid mode); `description` is the tooltip and `aria-description`; labels truncate with a title. A column drags only within its group (pointer and keyboard). Reads the `table` slot head height, weight and divider. `<DataGridVirtual>` takes the same `columnGroups`.',status:`live`},{title:"Column spanning (cell `colSpan`)",description:'Per-row override: `meta.colSpan?: (row, rowIndex) => number` on a column. When `> 1`, the cell expands across the next N - 1 visible columns; those columns\' cells render as empty for this row only. Useful for "section break" rows (subtotal rows that span every numeric column), category headers, or visually highlighting a single big value across an analytic table. Composes with pinning + group headers. Refs AG Grid `colSpan`.',status:`planned`},{title:"Row spanning (cell `rowSpan`)",description:'Per-column override: `meta.rowSpan?: (row, rowIndex, allRows) => number` — the cell extends vertically over the next N - 1 rows. Most common use: merging duplicate values in a sorted column (e.g. "Country" cells with the same value collapse into one tall cell). Pairs with `meta.aggregateRowSpan?: "sameValue" | "manual"` to auto-detect runs. Renders via real `<td rowSpan>` so screen readers + selection work correctly. Refs AG Grid `rowSpan`.',status:`planned`},{title:`Row numbers column`,description:"Built-in virtual column `meta.rowNumbers: true` (or shorthand prop `rowNumbers` on `<DataGrid>`) — renders a left-most monospace column showing the 1-indexed row position. Configurable: `start` (offset for pagination — auto-syncs with `pagination.page * pageSize`), `format: (n) => ReactNode` for custom rendering (Roman numerals, letters, etc.), `sticky` (pins under column-pin layer when horizontal scroll). Excludes from CSV / JSON exports unless `exportable: true`.",status:`planned`}]},{name:`Selection + bulk`,features:[{title:`Row checkboxes`,description:"Auto-rendered when `selectable !== false`. Selection state lifted to UI provider so a bulk bar can render anywhere.",status:`live`},{title:"`data-row-id` on every `<tr>`",description:"Stable row identifier emitted on every table row by `<DataGrid>`. Lets pointer-based selection hooks (rubber-band, long-press) work against the table view with zero extra wiring.",status:`live`},{title:`Shift-click range select`,description:`Plain click sets the anchor index; Shift-click any subsequent row extends the selection to every row between anchor and current. Works on the row body OR the checkbox cell.`,status:`live`},{title:`⌘/Ctrl-click toggle`,description:`Meta/Ctrl-click on a row toggles its selection without committing select mode (no anchor reset). Mix with shift-click for additive range builds — classic Finder/Mail behavior.`,status:`live`},{title:`Header indeterminate`,description:`Header checkbox: empty / indeterminate (some) / checked (all on this page). Click toggles.`,status:`live`},{title:"`<DataGridBulkActions>` bar",description:"Floating bottom bar visible when `selectedIds.length > 0`. Built-in Delete + custom children.",status:`live`},{title:`Adapter-driven Delete`,description:"Bulk Delete button auto-hides when adapter doesn't implement `bulkDelete`. No prop wiring.",status:`live`},{title:`Selection-aware bulk-edit`,description:"`<DataGridBulkEditPopover columns>` — column header menu shows \"Edit selected (N)\" when adapter has `bulkUpdate` AND col has `meta.edit` AND selection > 0. Dialog reuses the column's edit input (text/number/select) → dispatches `mutators.bulkUpdate(selectedIds, patch)`. Drawn by the overlay kit's modal: no close while the update runs, a failed update stays in the dialog as an inline error, focus returns to the column menu's trigger.",status:`live`},{title:`Selection indicator chip`,description:'`<DataGridSelectionIndicator />` — inline "N selected" chip with × Clear button. Layout-agnostic; mount in toolbar / page-header / sticky-footer. Hidden when count = 0 unless `alwaysShow`.',status:`live`},{title:`Auto-enter select-mode hook`,description:"`useDataGridSelectMode(count)` derives a layout-agnostic select-mode boolean from the live selection count. Returns `{ selectMode, enter, exit, reset }` for Apple-Photos-style explicit override. Used by MediaGrid; available for any layout.",status:`live`},{title:`Selection keyboard shortcuts`,description:"`useDataGridSelectionShortcuts({ hostRef, onSelectAll, onClear })` — ⌘A select-all + Esc clear as keyboard kit commands scoped to the grid element (`scope.datagrid-<n>`); ⌘A in a text field selects its text. Drop in any layout root; pair with layout-specific arrow nav.",status:`live`},{title:`Open a row from the keyboard`,description:"With `onRowClick` set, cards and `<DataGridVirtual>` rows are Tab stops (a kanban board is one, its arrows walk the cards) and **o** on the focused card or row opens it; Enter opens too when the row has no drag (on a draggable row Enter and Space pick it up). The keys are on each row as `aria-keyshortcuts` and listed in `<DataGridShortcutsHelp>`.",status:`live`},{title:`Rubber-band selection hook`,description:"`useDataGridRubberBand({ hostRef, selector, getRowId, onSelect })` — pointerdown drag-to-select marquee that hit-tests any element matching the selector. Default selector `[data-row-id]`. Plug into table list-view, cards, kanban, media-grid — selector is parameterized.",status:`live`},{title:`Long-press selection hook`,description:"`useDataGridLongPress({ selector, getRowId, onLongPress })` — touch long-press helper. Selector + row-id extractor parameterized, defaults to `[data-row-id]`. Suppresses the synthetic click via `shouldSuppressClick()`.",status:`live`},{title:`Drag-ghost pill helper`,description:'`buildDataGridDragGhost(count, { noun?: "row" / "card" })` — builds a tiny "N items" chip. The table view\'s row reorder renders it as the DnD-kit drag preview under the pointer (a `<tr>` cannot be cloned outside its table).',status:`live`},{title:`Clear selection mechanisms`,description:"Four entry points compose: Esc keyboard shortcut, × on `<DataGridSelectionIndicator>`, × on `<DataGridBulkActions>` bar, imperative `setSelectedIds([])` via `useDataGridUI()`.",status:`live`},{title:`Cell range selection`,description:"`cellSelection` on `<DataGrid>`: the table becomes a WAI-ARIA grid with one roving tab stop; press-and-drag (auto-scroll at the edges), Shift-click and Shift + arrows / Home / End / Mod+Home / Mod+End / PageUp / PageDown select a rectangle of data cells, Shift+Space the row, Mod+A every cell on the page, Esc clears it (then the rows). Enter, F2 or a click on the focused editable cell edits it. Long press then tap on touch; arrows mirrored in RTL. The range lives in `<DataGridUIProvider>` (`cellSelection` / `defaultCellSelection` / `onCellSelectionChange`, `selectedCellRange`), cleared on sort, filter, page and column changes. Keys are keyboard-kit commands (`datagrid.cell…`, `datagrid.extendRange…`). Utility columns are never in a range; row drag starts only from the grip. `<DataGridVirtual>` takes the same `cellSelection` (plus copy, paste, undo and `columnGroups`) over every row, with `aria-rowindex` / `aria-colindex` on the mounted window and keys that scroll the row in.",status:`live`},{title:`Cmd+C selection`,description:"With `cellSelection` on: Mod+C copies the cell range, else the selected rows (every visible data column, in display order), else the focused cell, as TSV through the spreadsheet kit's `toTsv` (or a `clipboardCodec`). Text per cell: `meta.copyValue(row)`, else `meta.edit.read`, else the row's own field, else `meta.searchValue`; `canRead` false copies empty. `copyHeaders` adds the header line; the right-click menu has Copy cells / Copy rows / Copy with headers. Read from the provider's rows, never the DOM.",status:`live`},{title:`Cross-page selection persistence`,description:"Picking 2 rows on page 1, 3 on page 2, 5 on page 3 → `selectedIds` accumulates all 10 ids in `<DataGridUIProvider>`. Selection survives page navigation in `paged` mode (and in `numbered` mode once shipped) — the UI provider state is page-agnostic; ids are kept in a Set keyed by `getRowId(row)`. Selected rows on a re-visited page automatically re-paint their checkboxes. Required across every layout (table / cards / kanban / media-grid).",status:`planned`},{title:`Select-all-matching flag`,description:'Sticky flag `selectionMode: "specific" | "all-matching"` in `<DataGridUIProvider>`. When `all-matching`, the selection conceptually includes *every row matching current filters / search / sort*, not just loaded ones — header checkbox flips to "All 12,480 selected" + "Clear" affordance, every row\'s checkbox paints checked regardless of which page is visible. Bulk actions dispatch either against the literal `selectedIds` (specific mode) or via a new adapter method `bulkUpdateMatching(where, patch)` / `bulkDeleteMatching(where)` (all-matching mode) so backends don\'t have to enumerate millions of ids. Gracefully falls back to `fetchAll() → enumerate` when the adapter doesn\'t implement the *Matching methods.',status:`planned`},{title:`Header checkbox three-state across pages`,description:`When the user has picked rows across multiple pages, the per-page header checkbox is computed only against the *current page's* rows, but a sibling "All N selected (every page)" badge appears in \`<DataGridSelectionIndicator>\` so users can tell which mode they're in. ⌘A on a focused grid offers "select all on this page" → "select all matching" (Gmail pattern).`,status:`planned`},{title:"Bulk-action adapter contract — `bulkUpdateMatching` / `bulkDeleteMatching`",description:"Optional adapter methods that receive the active `where` clause instead of an id array. Used by select-all-matching mode so the server can run `UPDATE … WHERE …` in one round-trip instead of N. Capability-detected by `inspectCapabilities()`; if absent, the kit falls back to `fetchAll() → bulkUpdate(allIds, patch)` (slower but works on any cursor adapter).",status:`planned`}]},{name:`Pagination`,features:[{title:"Pagination - Cursor-based prev/next (`paged` mode)",description:"Provider passes `first/after` (forward) or `last/before` (backward) to `adapter.load()`. Linear / GitHub-shape — works with any Relay-style backend. Default mode.",status:`live`},{title:`Pagination - Page size selector`,description:`Dropdown with caller-supplied options (default 10 / 20 / 50 / 100). Resets cursor to first page on change.`,status:`live`},{title:"Pagination - `<DataGridPageSizeSelect>` (mode-agnostic)",description:"Standalone page-size picker — works in `paged` / `infinite` / `numbered`. ui's `PaginationPageSize` (a `Select` named by its visible label, `Infinity` shown as \"All\", the current size always offered) wired to `useDataGridUI().pageSize`. `<DataGridPagination>`'s \"Rows per page\" control is the same part. Useful when you want the size selector decoupled from the prev/next paginator (e.g. you're using `<DataGridNumberedPagination>` which doesn't bundle one).",status:`live`},{title:"Pagination - `<DataGridPaginationStatus>` (mode-aware readout)",description:'Shape-shifts on `paginationMode`: `paged` → "Showing 21–40 of 213"; `numbered` → "Page 3 of 27 · 530 results"; `infinite` → "Loaded 90 of 800" (or "Loaded 90" when total unknown). Optional `format` prop overrides the rendered string entirely for i18n / custom shape.',status:`live`},{title:`Pagination - Row range readout`,description:'"1–20 of 213" rendered when `totalCount` is supplied by the adapter.',status:`live`},{title:`Pagination - Auto-reset on filter change`,description:`Pagination jumps back to page 1 whenever search / filters / sort change.`,status:`live`},{title:`Pagination - Infinite scroll (auto-sentinel)`,description:'Set `<DataGridProvider paginationMode="infinite">` and mount `<DataGridInfiniteAnchor direction="up | down" />` anchors. Cursor pages append (down) or prepend (up) into the same `rows` array. Live at `/kits/datagrid/infinite` (table) and `/kits/datagrid/media` (gallery).',status:`live`},{title:`Pagination - Bidirectional infinite`,description:'Both `direction="up"` and `direction="down"` anchors supported. `up` fires when user lands mid-feed via deep-link cursor and scrolls up; provider issues backward cursor query and prepends results.',status:`live`},{title:`Pagination - IntersectionObserver sentinel hook`,description:"Layout-agnostic `useDataGridInfiniteScrollSentinel({ enabled, onTrigger, rootRef?, rootMargin? })` — bring your own UI; the hook just attaches an observer to a sentinel ref. Powers `<DataGridInfiniteAnchor>` and any custom load-more affordance.",status:`live`},{title:`Pagination - Windowed renderer (virt)`,description:'Drop-in `<DataGridVirtual>` powered by `@tanstack/react-virtual` — flat (`/kits/datagrid/virtual`) or with sticky group headers, Linear-style (`/kits/datagrid/grouped`). 5,000 rows scroll at 60fps. Composes with `paginationMode="infinite"` — fetch in pages, render only the window.',status:`live`},{title:"Pagination - Numbered offset mode (`numbered`)",description:'New `<DataGridProvider paginationMode="numbered">`. Adapter accepts `{ offset, limit }`; provider derives offset from page number. Backed by `<DataGridNumberedPagination>` default UI. Required for "jump to page 17" / "page 1 of 42" UX. Adapter capability flags (`cursorPagination` / `offsetPagination`) detect support automatically.',status:`live`},{title:"Pagination - `<DataGridNumberedPagination>` (ellipsis)",description:"Default UI for numbered mode. Renders `1 2 3 … 17 18 19 [Next]` with adaptive ellipsis compression based on `totalPages`. Keyboard-navigable (←/→/Home/End).",status:`live`},{title:"Pagination - `<DataGridJumpToPage>`",description:"Inline `Go to page __` input for numbered mode: ui's `PaginationJumpToPage` wired to the numbered pager. The typed page is clamped to `totalPages` before dispatching; Enter or Go jumps, Escape clears; the visible label names the input; no inner `<form>`, so it sits inside a host form, and two grids never share an id.",status:`live`},{title:"Pagination - `<DataGridFirstLastButtons>` (⏮ ⏭)",description:"First / Last quick-jump controls. Works with both `paged` (cursor reset to head/tail) and `numbered` (jump to page 1 / totalPages). Disabled when `hasPrev` / `hasNext` is false.",status:`live`},{title:"Pagination - `<DataGridLoadMoreButton>` (manual infinite)",description:'Manual variant of `<DataGridInfiniteAnchor>` — same `infinite.loadMore()` hook, but waits for an explicit button click instead of auto-firing on scroll. Pinterest / "Load more results" pattern. Live at `/kits/datagrid/load-more`.',status:`live`},{title:"Pagination - `useDataGridPagination()` unified hook",description:"One discriminated-union hook abstracts all three modes (`paged` / `infinite` / `numbered`). Build your own pagination UI in ~20 lines — works for any mode, switches gracefully when the provider mode flips.",status:`live`},{title:`Pagination - Adapter offset/limit query fields`,description:"`DataGridQuery` gains optional `offset` + `limit` (additive, non-breaking). `inspectCapabilities(adapter)` reports `cursorPagination` / `offsetPagination` flags. Adapters can support either, both, or neither.",status:`live`},{title:`Pagination - Capability-mismatch guard`,description:'At mount the provider throws a named error when `paginationMode="numbered"` meets a cursor-only adapter, or the reverse, so the mismatch fails loudly instead of leaving an empty grid.',status:`live`},{title:`Pagination - Date-bucket separator`,description:'Ships as `defineDateBucketColumn<TRow>({ bucketKey, format })` (factory) + `<DataGridDateBucketActivator>` (imperative activator). Piggy-backs on the existing groupBy infra — `meta.groupValue` + `meta.groupLabel` extractors render "Today" / "Yesterday" / "Mar 14" section headers between rows. Works on top of *any* pagination mode (paged / infinite / numbered) because it groups whatever the renderer is showing. Helpers `startOfDayKey()` + `formatRelativeDay()` exported for the common Slack-style label set. Live at `/kits/datagrid/log-stream`.',status:`live`},{title:"Pagination - `<DataGridLiveTail>`",description:'Sticky "N new ↓" badge + auto-scroll-to-bottom + pause-on-hover / manual scroll. State machine: `following → paused → following`. Detects new rows via `useDataGrid().rows.length` delta — provider grows that array via `adapter.subscribe` push, `loadMore` cursor append, or manual refresh; all three trigger the same code path. Composes with any pagination mode. Configurable `pauseWhen` (hover / manualScroll) + `stickThreshold` + `badge` render override. tail -f / Datadog Logs shape. Live at `/kits/datagrid/log-stream`.',status:`live`},{title:`Pagination - "All" / unpaginated`,description:"Set `defaultPageSize={Infinity}` on `<DataGridUIProvider>` and skip the paginator entirely. Adapter returns everything; renderer (use `<DataGridVirtual>` for thousands+) decides what to show.",status:`live`},{title:"Pagination - Keyset / `search_after`",description:"Server-side cursor variant where the cursor is the values of the last row's sort columns (e.g. `(created_at, id)`) rather than an opaque token. Server queries `WHERE (sortCols) > (lastValues) LIMIT n` — uses the sort index, faster than offset at scale. Used by Elasticsearch (`search_after`), MongoDB, most big-data systems. From the kit's perspective looks identical to cursor; server picks the encoding. Will document the recipe + ship a reference encoder/decoder helper.",status:`planned`},{title:`Pagination - Hybrid cursor + jump-to-anchor`,description:`Bluesky-style "jump to date" — combine cursor pagination with named anchor points (date / id / user-supplied key). Calendar scrubber or timeline UI dispatches to a specific anchor; provider resets cursor + bidirectional infinite takes over from there.`,status:`planned`},{title:`Pagination - Hash / random-sampling feeds`,description:'TikTok-style ranked feeds — each scroll fetches a *fresh sample* rather than the "next page." Cursor is a session/seed used by a recommendation engine, not an order-stable position. No total count, no jump-to-N. Adapter exposes `loadSample(seed, n)` instead of paged `load()`. Recommendation engine is out of the kit\'s scope; this entry is a placeholder for when we wire the UI affordances.',status:`planned`}]},{name:`Row actions`,features:[{title:`Left inline icon-button strip`,description:"`leftActions={(row) => ActionItem[]}` renders a tooltipped icon-button row at the left of every row.",status:`live`},{title:`Right inline icon-button strip`,description:"`rightActions={(row) => ActionItem[]}` mirrors the left side.",status:`live`},{title:`Left ellipsis menu`,description:"`leftMenuActions={(row) => ActionItem[]}` adds a dropdown on the left.",status:`live`},{title:`Right ellipsis menu`,description:"`rightMenuActions={(row) => ActionItem[]}` — auto-derived from adapter when not supplied.",status:`live`},{title:`Right-click context menu`,description:"`useRowContextMenu` portal'd, smart-positioned (stays on-screen), Esc + outside-click dismiss. Same `ActionItem` shape.",status:`live`},{title:`Built-in Copy ID + Copy as JSON`,description:"Free in every context menu unless `hideCopyHelpers`.",status:`live`},{title:`Confirm dialog action variant`,description:"`{ confirm: { title, message, destructive, onConfirm } }` — opens `<ConfirmDialog>` with async-aware loading state.",status:`live`},{title:`URL action variant`,description:'`{ url: "/path" }` renders as an anchor for navigation actions.',status:`live`},{title:`Adapter-derived defaults`,description:"`useDefaultRowActions()` auto-builds Edit / Duplicate / Delete from `mutators.duplicateRow / deleteRow`. Caller-supplied props extend or replace.",status:`live`}]},{name:`Row reorder`,features:[{title:`Drag handle column`,description:"GripVertical handle auto-appears as the leftmost column when adapter implements `moveRow`. Hide via `enableRowReorder={false}`.",status:`live`},{title:`Single-row drag`,description:`Press anywhere on the row (or Space on the grip, then arrows, then Space; Escape cancels) — DnD kit. The pointer's half of the hovered row picks before / after (2px primary line on that edge); dropping after the last row appends. Drops that change nothing never reach the adapter. Each step is announced through the kit's live region.`,status:`live`},{title:`Multi-select bulk drag`,description:"Select N rows, then drag any selected row → all selected move together to the drop point in their original order. Routes to `mutators.bulkMoveRows`.",status:`live`},{title:`Adapter mutators`,description:"`moveRow(rowId, beforeRowId)` + `bulkMoveRows(rowIds, beforeRowId)`. `null` beforeId appends. UI hides when neither is implemented.",status:`live`},{title:`Drag visuals`,description:`Every row of the dragged batch: opacity-40. A "N rows" pill follows the pointer. Drop target: 2px primary line on the top or bottom edge.`,status:`live`},{title:"Row reorder in `<DataGridVirtual>`",description:"Set `enableRowReorder` on `<DataGridVirtual>` — each windowed row becomes a drag source + drop target. Uses the *free-flow* drag hook (DnD kit, clone preview capped at 360px) so the dragged row follows the cursor; the kit auto-scrolls the pane near its edges, and in `icon` mode Space on the grip drags by keyboard. Vertical drop-side math: top half = before / bottom half = after. Caveat: only currently-rendered rows are valid drop targets — virt recycles DOM.",status:`live`},{title:"Row reorder in `cardsLayout`",description:"Set `enableRowReorder: true` on the layout factory — each card becomes a drag source + drop target. Uses the *free-flow* drag hook so the card visually lifts and follows the cursor (Trello / Linear feel). Horizontal drop math (left / right halves). Source card fades to 40% opacity while its clone floats. Multi-drag shows a stack of clones with a count badge (the kit's `stackedPreview`).",status:`live`},{title:`Drag-reorder — two flavors, one hook surface`,description:'Two hooks ship side by side: `useDataGridRowDragReorder` ("N rows" pill preview, used by `<DataGrid>` table view) and `useDataGridFreeFlowDragReorder` (clone of the row follows the cursor — "lift and float" feel, used by `<DataGridVirtual>` + `cardsLayout` + MediaGrid). Both are presets over `useRowReorderDnd` on the in-repo DnD kit (pointer, touch, keyboard, announcements). Both share `{ enabled, rowIds, selectedIds, orientation, onMove }` API + auto-dispatch via the same `dispatchRowMove(mutators, ids, beforeId)` helper. Pick the flavor that matches your UX target.',status:`live`},{title:"Drag-handle modes — `whole-row` vs `handle` vs `none`",description:'Layouts now expose a `dragHandle` option that picks where the drag originates. `whole-row` / `whole-card` (cards default): pointerdown anywhere on the row lifts it. `icon` (virt default, opt-in for cards): the layout renders a built-in `<GripVertical>` grip; only the handle drags. `none`: no auto-handle — caller mounts `<DataGridRowDragHandle rowId>` inside cell renderers. Resolved internally as `mode: "whole-row" | "handle"` on the hook + a `handleProps(rowId)` slot function that any element can spread.',status:`live`},{title:"`<DataGridRowDragHandle>` (place handles anywhere)",description:"Drop-in handle component. Mount inside any cell renderer / custom slot — multiple handles per row supported. `asChild` (Radix-style) merges drag props onto your child element so `<Button>` / icons / links can become handles without wrapper divs. Reads the layout's `<DataGridReorderProvider>` context; renders pass-through when reorder is off so it's safe to leave permanently in cell renderers.",status:`live`},{title:"`<DataGridReorderProvider>` + `useDataGridReorder()` context",description:'Layouts publish `{ handleProps, isDragSource, mode: "whole-row" | "handle" | "off" }` so descendants can mount drag affordances without prop drilling. Custom layouts wrap their subtree in `<DataGridReorderProvider value={...}>` and expose the same hook for any future handle-style primitive. The "off" mode lets handle components no-op cleanly when reorder isn\'t active.',status:`live`},{title:`Row drag grid-to-grid`,description:'Drag rows from one `<DataGrid>` and drop into another. Each grid declares `dragNamespace?: string` — drags only cross between grids sharing the same namespace (or wildcard). Drop dispatches the target grid\'s `adapter.acceptDroppedRows?(rows, beforeRowId)` (new optional mutator) so target backends can claim ownership. Source grid removes via `adapter.removeRow / bulkDelete` (optional). Capability-detected; auto-hides when either side opts out. Useful for "move users between teams" / "assign tickets to project" UIs.',status:`planned`},{title:`Row drag to external drop zone`,description:'Wrap any element in `<DataGridRowDropZone onDrop={(rows) => …}>` — it auto-registers as a valid drop target for any grid using the same `dragNamespace`. Receives the moved rows; caller decides what to do (open detail pane, file as attachment, send to API, anything). Visual hover state via `data-drop-active="true"` for CSS theming. Composes with both the pill and free-flow drag flavors.',status:`planned`}]},{name:`Saved views`,features:[{title:"`<DataGridViewSelector>`",description:`Bookmark dropdown listing All + builtin + user views. Modified-state dot when state diverges.`,status:`live`,shortcut:`v`},{title:`Pluggable storage`,description:"`ViewStorage` interface — default `LocalStorageViewStorage`, swappable for server-backed.",status:`live`},{title:`Captures full snapshot`,description:`search + filters + sort + hidden columns + column order + column sizes — all replay on select.`,status:`live`},{title:`Save as new view`,description:"`<SaveViewDialog>` reusable for save / rename / save-as flows.",status:`live`},{title:`Save changes (in-place)`,description:`"Save changes" item appears for non-builtin views when state diverges.`,status:`live`},{title:`Favorites + default pin`,description:`Star a view to surface it. Pin one as default — auto-applies on mount.`,status:`live`},{title:`Built-in views`,description:"Ship read-only views via the `builtinViews` prop. Can't be deleted; can be duplicated by Save-as.",status:`live`},{title:`Smart suggestions`,description:`After 2+ visits with the same filter shape, prompt: "Save this view?".`,status:`planned`}]},{name:`Density + chrome`,features:[{title:`Density toggle`,description:`Compact vs. comfortable. Affects row padding + cell text size.`,status:`live`},{title:`Sticky header`,description:"Header stays pinned during vertical scroll. Toggle via `stickyHeader` (default true).",status:`live`},{title:`Loading skeleton`,description:"Animated skeleton rows on initial load. Caller can supply a custom node via `loading={…}`.",status:`live`},{title:`Empty state`,description:'"No rows" or caller-supplied `empty={…}` element when `rows.length === 0`.',status:`live`},{title:`Auto density`,description:'`densityMode: "auto"` switches compact ↔ comfortable via a media query (compact < 768px). Three-state toggle in `<DataGridDensityToggle>` — Compact / Comfortable / Auto.',status:`live`},{title:`Programmable row accent`,description:'`rowAccent={(row) => "success" | "warn" | "danger"}` on `<DataGridView>` — paints a 2px left border across table rows / cards / kanban tiles.',status:`live`},{title:`Scrollable rows + sticky header`,description:"Wrap `<DataGrid>` in a height-bounded container (`max-h-[520px] overflow-y-auto`) and the header stays pinned while only the rows scroll. Works with `<DataGridVirtual>` natively (height is a required prop). For `<DataGrid>`, a new convenience prop `viewport: { maxHeight }` will ship the wrapper + sticky-header chrome out of the box.",status:`planned`},{title:"`<DataGridStatusBar>`",description:'Bottom-of-grid status strip — "N rows · M selected · X filtered". Mode-aware: shows page range in `paged` mode, "Loaded N of M" in `infinite`, "Page X of Y" in `numbered`. Reads from `useDataGrid()` + `useDataGridPagination()`. Slot for custom right-side content (last-updated timestamp, sync state, etc.). Auto-collapses to one line on narrow viewports.',status:`planned`},{title:`Freeze top N rows`,description:'`<DataGrid frozenTopRows={1} />` (or `frozenBottomRows`) — pin the first / last N rows so they stay visible while the rest scroll. Useful for "totals" rows, "summary" rows, important pinned items. Composes with column pinning + group headers. Renders via `position: sticky` on the chosen rows + computed cumulative offsets so multiple frozen rows stack correctly.',status:`planned`}]},{name:`Layouts`,features:[{title:"Pluggable `DataGridLayout`",description:"Interface `{ id, label, icon, render(ctx) }` — built-in `table` always present; pass extra layouts via `<DataGridView layouts>`. `LayoutCtx` exposes rows, columns, selection, density, empty / loading states, row-action hooks.",status:`live`},{title:"`<DataGridLayoutSwitcher>`",description:"Segmented toolbar control. Auto-prepends Table; hide via `hideTable`. Persists to `useDataGridUI().layoutId` so URL state captures it.",status:`live`},{title:`Cards layout`,description:"`cardsLayout({ headlineColumnId, subheadColumnId, bodyColumnIds, minCardWidth, footer })` — responsive grid of cards, same data + selection + actions + context menu as the table.",status:`live`},{title:`Kanban layout`,description:'`kanbanLayout({ groupBy, columns, patchFor })` — group-by-column board. Drag a card to another column dispatches `mutators.updateRow(id, patchFor(key))`. Auto-shows empty "Drop here" zones. DnD kit: columns are container targets (highlighted via `data-dnd-over`), a selected batch moves together (stacked preview), and the keyboard drags too (one tab stop for the board, arrows walk cards, Space picks up, arrows step columns, Space drops).',status:`live`},{title:`MediaGrid layout`,description:"`mediaGridLayout({ thumbUrl, thumbKind, title, subtitle, actions, onOpen, aspect, columns })` — Google-Photos-style gallery view. See the dedicated MediaGrid group for the full breakdown. Demo: `/kits/datagrid/media`.",status:`live`}]},{name:`MediaGrid`,features:[{title:`MediaGrid - Gallery view`,description:"Render datagrid rows as cards with thumbnail + title + actions. Plug via `<DataGridView layouts={[mediaGridLayout()]} />`. Same selection / bulk / search / pagination / saved-views state as table view.",status:`live`},{title:`MediaGrid - Type-aware thumbnails`,description:"Default `<MediaGridThumb>` paints `<img>` for image, `<video poster>` for video, kind-specific Lucide icon for audio / pdf / archive / code / folder / unknown. Override via `options.Thumb`.",status:`live`},{title:`MediaGrid - Hover checkbox`,description:`Circle ✓ chip top-left, hidden until card is hovered or selected. Click stops propagation so card body click stays separate.`,status:`live`},{title:`MediaGrid - Auto-enter select mode`,description:"Google-Photos pattern wired via the layout-agnostic `useDataGridSelectMode(count)` hook: first ✓ flips select mode on; selection cleared → mode flips off. While in mode, body click toggles selection instead of opening the card. Override the auto behavior with `enter()` / `exit()`.",status:`live`},{title:`MediaGrid - Body click semantics`,description:"Outside mode: `onOpen(row)`. Inside mode: toggle selection. ⌘/Ctrl-click always toggles without auto-entering mode. Shift-click extends a range from the last selected card.",status:`live`},{title:`MediaGrid - Range select (shift-click)`,description:`Shift-click between two cards selects every card in between in geometric order. Anchor is the last-clicked card.`,status:`live`},{title:`MediaGrid - Drag-rectangle (rubber-band)`,description:"Thin wrapper around the generic `useDataGridRubberBand` pre-bound to `[data-media-grid-card]`. Pointerdown on grid background OR Shift/Cmd-pointerdown on a card → marquee. 5px threshold, additive-on-Shift, modifier suppresses HTML5 drag-reorder.",status:`live`},{title:`MediaGrid - Long-press on touch`,description:"Thin wrapper around the generic `useDataGridLongPress` pre-bound to `[data-media-grid-card]`. Hold a card ~450ms → enter select mode + toggle. Synthetic click suppressed.",status:`live`},{title:`MediaGrid - Keyboard nav`,description:"Roving focus from `@kitora/keyboard/roving`: one Tab stop for the grid, arrow keys move geometrically (columns read live from `grid-template-columns`), Home/End and PageUp/PageDown too. Space toggles, Enter opens. ⌘A select-all and Esc clear are wired by the layout-agnostic `useDataGridSelectionShortcuts` hook (also exported for any other layout).",status:`live`},{title:`MediaGrid - Card action overlay`,description:"Bottom-right hover-revealed icon row (Preview / Open / etc.) via `options.actions: (row) => [{ id, label, Icon, onClick, hidden? }]`. Auto-hidden while in select mode so clicks land on selection toggle.",status:`live`},{title:`MediaGrid - Title + subtitle meta`,description:"Optional `options.title` / `options.subtitle` (any ReactNode) renders below the thumb. Override via `options.Meta` to ship tag chips, status pills, byline rows.",status:`live`},{title:`MediaGrid - Responsive columns`,description:"`options.columns: { default, sm, md, lg, xl }` maps to Tailwind breakpoints. Defaults: 2 / 3 / 4 / 5 / 6. Aspect ratios: `square` (default), `4/3`, `16/9`, `3/4`, `auto`.",status:`live`},{title:`MediaGrid - Override Card / Thumb / Checkbox / ActionOverlay / Meta`,description:"Every renderer slot accepts a custom React component. Pass `options.Card`, `options.Thumb`, etc. to fully reskin while keeping the interaction layer intact.",status:`live`},{title:`MediaGrid - Reusable hooks`,description:"Low-level building blocks exported for custom layouts: `useMediaGridSelectMode`, `useMediaGridRubberBand`, `useMediaGridLongPress`, `useMediaGridKeyboardNav`. Compose your own gallery from scratch.",status:`live`},{title:"MediaGrid - `data-*` selection hooks",description:"Each card carries `data-media-grid-card`, `data-row-id`, `data-selected`, `data-select-mode`. Style hover / active states from CSS without React state.",status:`live`},{title:"MediaGrid - `thumbOverlay` slot",description:`Per-row absolute overlay above the thumbnail — drop in selection badges, durations, type chips.`,status:`live`},{title:`MediaGrid - Drag selection visual`,description:`Live primary-tinted marquee rectangle painted during rubber-band drag. Hidden when no active drag.`,status:`live`},{title:`MediaGrid - Bulk-action bar`,description:"Reuses `<DataGridBulkActions>` — built-in Delete + custom action slots fire against `selectedIds` no matter how rows were selected (click / shift / rubber-band / long-press / ⌘A).",status:`live`},{title:`MediaGrid - URL state`,description:"Layout id `media-grid` persists via `useDataGridUrlSync` like every other layout. Bookmark / share the gallery view directly.",status:`planned`},{title:`MediaGrid - Drag-to-reorder`,description:"Drag a card on the DnD kit (or a card that is part of the active selection — the whole selection moves, shown as a stack with a count badge) onto another card. A Shift / Cmd / Ctrl press is rubber-band selection, never a reorder; the keyboard keeps Space = select (the kit's `none` policy). Cursor in left half = drop before, right half = drop after. Dispatches `mutators.bulkMoveRows(ids, beforeRowId)` or replays sequential `mutators.moveRow` when only the single mutator exists. Live primary drop indicator on the target edge.",status:`live`},{title:`MediaGrid - Drag-to-upload zone`,description:`Empty-state + grid-background dropzones for file uploads. Hook into your storage adapter.`,status:`planned`},{title:`MediaGrid - Infinite scroll`,description:'Flip the provider to `paginationMode="infinite"` and mount `<DataGridInfiniteAnchor direction="down" />` below the grid. Cursor pages append into the same `rows` array; bidirectional `direction="up"` is supported too (loads earlier pages from a `hasPreviousPage` cursor). Composes with virt — `<DataGridVirtual>` already windows the rendered range.',status:`live`},{title:`MediaGrid - Layout switcher (Tile / Table)`,description:"In-grid toggle to flip between MediaGrid (tile view) and table view of the same dataset. Reuses `<DataGridLayoutSwitcher>` + persists pick via `useDataGridUI()`. Keeps selection / filters / sort / search shared across both views so users can pivot without losing context.",status:`planned`}]},{name:`Inline editing`,features:[{title:`Click-to-edit cells`,description:'Per-column `meta.edit: { type: "text" | "number" | "select", … }` — double-click cell to enter edit mode. Enter commits, Esc cancels, blur commits. Routes through `mutators.updateRow`.',status:`live`},{title:`Custom read / patch`,description:"`meta.edit.read(row)` to extract the current value; `meta.edit.patch(value)` to translate the new value into a `Partial<TRow>` patch (`ColumnEditConfig<TRow>` is typed per row; `patch` is required so the column narrows the editor value to its field). `read` defaults to `row[id]`.",status:`live`},{title:`Auto-hides without mutator`,description:"When the adapter doesn't implement `updateRow`, the cell falls back to read-only render with no extra wiring.",status:`live`},{title:`Paste from a spreadsheet`,description:"With `cellSelection` on: Mod+V (or the context menu's Paste) decodes TSV from Excel, Sheets or Numbers with the spreadsheet kit's `parseTsv` (quoted multi-line cells included) or a `clipboardCodec`, lands it from the range's top-left cell, tiled when the range is a whole multiple of the block (`pasteTarget`) and clipped at the last visible row and column. Only `meta.edit` cells whose row passes `canEdit` are written, coerced like the editors (numbers, select value then label); each row's cells become one `updateRow` patch (optimistic). `onPaste({ applied, skipped })`; announced. Without `updateRow` the event goes to the browser.",status:`live`},{title:`Undo / redo of edits`,description:'On by default when the adapter has `updateRow` (`<DataGridProvider history>`: `true` = 100 steps, `{ limit }`, `false` off), on the collab kit\'s `createHistory`. Mod+Z / Mod+Shift+Z / Ctrl+Y inside the grid (`datagrid.undo` / `datagrid.redo` keyboard commands; a text field keeps its own undo). An inline edit, a paste and a bulk edit are one step each (bulk edit undoes each row to its own previous value). A rejected undo / redo write drops that step and announces "Undo failed: …". `<DataGridUndoRedo>` toolbar buttons and `useDataGridHistory()`. `refresh()` and a new adapter clear it. Filter, sort, column and view changes are not tracked.',status:`live`},{title:`Optimistic update`,description:"UI updates locally before the adapter resolves so edits feel instant. Rolls back the snapshot on error. Driven by the same `optimistic` flag as bulk mutators.",status:`live`},{title:`Inline add row (top / bottom)`,description:'New `<DataGridInlineAddRow position="top | bottom">` primitive — drops an editable composer row at the top or bottom of the grid (configurable). Tab through fields, Enter commits, Esc discards. Routes through a new optional `adapter.createRow?(patch) → MaybePromise<TRow>` mutator. Auto-hides when adapter doesn\'t implement it. Composes with every pagination mode (paged / infinite / numbered) — composer sits outside the paged window so it never gets paginated away. Per-column control via `meta.create` (mirror of `meta.edit` shape) — choose which fields are required vs auto-defaulted, custom validators, placeholder text. Multiple inline-add slots supported (e.g. top + bottom simultaneously).',status:`planned`},{title:"Adapter `createRow` mutator",description:'Optional `adapter.createRow?(patch: Partial<TRow>) → MaybePromise<TRow>` — server returns the canonical row (with id, server-defaulted fields). Provider prepends / appends to `rows` based on the composer\'s `position`. Capability-detected by `inspectCapabilities().createRow`; UI affordances auto-hide when absent. Pairs with `<DataGridInlineAddRow>` + any custom "Add row" button you build on `useDataGrid().mutators.createRow`.',status:`planned`}]},{name:`Row grouping + tree`,features:[{title:`Right-side detail drawer`,description:"`<DataGridDetailDrawer title body footer>` — driven by `useDataGridUI().detailRowId`. Click a row to open; reads the live row so mutations refresh in place.",status:`live`},{title:`Group by column`,description:"`<DataGridGroupBy columns>` toolbar dropdown — pick any column with `meta.groupable` (or `sortFieldId`). Renders collapsible group header rows with chevron + count badge + group-level select-all checkbox. State (active group + collapsed keys) persists in `useDataGridUI`. Custom `meta.groupValue` / `meta.groupLabel` for non-trivial keys.",status:`live`},{title:`Async row expansion`,description:"Adapter `loadChildren?(rowId)` → chevron column on every row. Click → loads children (cached per rowId, dedup'd in-flight), renders nested rows with depth-based indent. Recursive — children can themselves expand. Loading dot shown while in-flight. Empty `[]` marks leaf and hides chevron.",status:`live`},{title:`Aggregations / footers`,description:'`meta.aggregate: "sum" | "avg" | "min" | "max" | "count" | "countDistinct" | (rows) => ReactNode` — `<tfoot>` row auto-renders when any column declares one. Built-ins read `row[id]` (override via `aggregateRead`).',status:`live`},{title:`Inline row detail (expandable panel)`,description:"Click a row's detail chevron → an inline detail panel slides down between rows (Notion / Airtable shape). Distinct from the right-side drawer — keeps the user in-context rather than opening a side pane. Caller supplies `renderDetail: (row) => ReactNode`; multiple rows can be expanded simultaneously; expansion state persists in `useDataGridUI`. Composes with virt + group-by.",status:`planned`},{title:`Master / detail`,description:'A clicked row mounts a *detail grid* fed by `adapter.loadDetail(rowId) → DataGridAdapter<TDetail>`. Two grids share the page; selecting a different master row swaps the detail adapter. Compatible with both right-side drawer + inline panel placements via a `slot` prop. Useful for "orders + line items", "customers + transactions" shapes.',status:`planned`},{title:`Nested grids (grid-in-row)`,description:"A column cell whose `cell: (row) => <DataGrid>` mounts a fresh grid inside an expanded row. Each nested grid has its own provider pair, adapter, columns. Independent selection / pagination per nested grid; parent state untouched. Useful when relational data is deeper than 2 levels and a single tree expansion isn't enough.",status:`planned`},{title:`Pivot mode`,description:"New `<DataGridProvider pivotMode>` flag. Caller declares one or more `groupByColumnIds` (row groups) + one or more `pivotColumnIds` (whose distinct values become *generated* columns) + one or more `valueColumnIds` (whose aggregates fill the pivot cells, sum / avg / count / etc.). Result: a crosstab — e.g. rows = teams, columns = months derived from the data, cells = sum of revenue. Provider materializes the new schema; existing renderer (`<DataGrid>` / `<DataGridVirtual>`) draws it as a regular grid. Pivot state persists in `useDataGridUI`. Sidebar `<DataGridPivotPanel>` lets users drag fields between Rows / Columns / Values. Refs AG Grid pivot mode.",status:`planned`}]},{name:`Realtime`,features:[{title:`Adapter subscribe — realtime push`,description:"Optional `adapter.subscribe(handlers) → unsubscribe` opens a push channel; provider patches `rows` on each `onUpsert(row)` (insert-or-update by id) + `onRemove(rowId)`. Capability-detected (`inspectCapabilities(adapter).subscribe`). Reference `createInMemoryAdapter` exposes a `push(row)` / `remove(rowId)` hatch so demos + tests can drive realtime without a fake WebSocket — see `/kits/datagrid/log-stream`. Pairs with `<DataGridLiveTail>` for auto-scroll on push.",status:`live`},{title:`Optimistic mutators`,description:"Provider snapshots `rows` + `pageInfo` + `totalCount`, applies the mutation locally before the adapter resolves, restores on error. Default on; opt out via `<DataGridProvider optimistic={false}>`. Wraps `updateRow / deleteRow / bulkUpdate / bulkDelete`.",status:`live`}]},{name:`Toolbar / export`,features:[{title:"`<DataGridFilterBar>`",description:`Search + Filter picker + pills + Clear + right slot. Composes everything from the providers.`,status:`live`},{title:`Custom toolbar slot`,description:"Drop arbitrary toolbar children to the left of Sort / Views / Density via `rightSlot`.",status:`live`},{title:`CSV export`,description:"`<DataGridExportButton fields>` — dropdown with Current page (no extra request) + All matching rows (paginated via `fetchAll`). Respects current filters / sort / search.",status:`live`},{title:"`fetchAll` paginator",description:"Exposed on `useDataGrid()`. Loops cursor pagination using current filters / sort / search. `batchSize`, `maxRows`, AbortSignal supported.",status:`live`},{title:`CSV helpers`,description:"`csvEscape`, `rowsToCsv`, `downloadCsvString`, `downloadCsv` — dependency-free utils, exported individually for custom export flows.",status:`live`},{title:`JSON / Markdown export`,description:'Pass `formats={["csv","json","markdown"]}` to `<DataGridExportButton>` — dropdown groups items per format. Helpers: `rowsToJson`, `downloadJson`, `rowsToMarkdown`, `downloadMarkdown`.',status:`live`},{title:`Print the table`,description:'New `<DataGridPrintButton>` + `useDataGridPrint()` hook — opens the browser print dialog with print-optimized CSS (`@media print` rules ship in the kit) that strips selection checkboxes, action menus, and toolbar chrome; expands sticky headers; serializes hidden columns visibly; expands every group; pages rows by `pageSize-per-page` or `fit-to-page-height`. Optional `mode: "current" | "all"` — print just the current page or fetch every row first via `fetchAll`. Custom header / footer slots for company logo, watermark, generated-at timestamp.',status:`planned`}]},{name:`Keyboard`,features:[{title:`Single-letter shortcuts`,description:"/ → search · f → filter · s → sort · v → views · c → columns · ? → help. `@kitora/keyboard` commands (`datagrid.*`): inside a host `KeyboardProvider` they join its shortcuts editor, cheatsheet and palette and can be remapped or turned off (WCAG 2.1.4); without one the grid runs its own engine.",status:`live`},{title:`Arrow-key list navigation`,description:"`useListNavigation` hook used by every dropdown, on the keyboard kit's roving maths. Up/down/Enter; Home/End jump to ends; modified keys are left to the field.",status:`live`},{title:`Skips inputs`,description:`The keyboard kit's input policy keeps the single keys out of inputs, textareas, selects and contenteditable, and off Ctrl / ⌘ / Alt combos, so typing isn't intercepted.`,status:`live`},{title:`Shortcuts help dialog`,description:"`<DataGridShortcutsHelp>` lists every shortcut grouped by section; command rows show the current keys from the host's keyboard provider (a remap shows here). Opens on `?`. Override sections via the `sections` prop.",status:`live`,shortcut:`?`},{title:"`<DataGridShortcuts>` binder",description:"Drop-in side-effect component that registers `/`, `f`, `?` as keyboard kit commands wired to the UI provider, plus optional `s`, `v`, `c`. Skips inputs / contenteditable.",status:`live`}]},{name:`URL state + history`,features:[{title:`URL state sync`,description:"`useDataGridUrlSync({ namespace })` — search / filters / sort / pagination / view / hidden cols / column order / density / layout encoded in querystring. Back-button restores via popstate; share-link replays everything. `exclude` keeps chosen pieces out of the URL (neither read nor written).",status:`live`},{title:`Url codec`,description:"`readUrlState` / `writeUrlState` exported individually for callers that wire their own router (TanStack Router, Next.js App Router) instead of the default `history.replaceState`.",status:`live`},{title:`Reducer + history`,description:`Single reducer drives UI state. Cmd+Z undoes the last filter / sort / column / view change. (Undo of edits is live: see Inline editing → Undo / redo of edits.)`,status:`planned`}]},{name:`Internationalization`,features:[{title:`Localizable labels`,description:'New `<DataGridIntlProvider labels={{...}}>` — overrides every user-facing string the kit renders ("Search…", "Filter", "Sort", "1–20 of 213", "No rows", "Load more", every column-menu item, every confirm-dialog button). Ships a typed `DataGridLabels` interface so missing keys are caught at compile time. Plays nicely with i18next / react-intl / formatjs — pass a `t()`-driven object. Per-instance scope (no global singleton).',status:`planned`},{title:`Number / date formatters`,description:'Per-column `meta.format: { kind: "number" | "currency" | "date" | "datetime" | "relative", locale?, options? }` (Intl.NumberFormat / DateTimeFormat / RelativeTimeFormat under the hood). Defaults inherit from `<DataGridIntlProvider locale>` — every formatted cell respects locale + numbering / calendar systems automatically.',status:`planned`},{title:`Design language table slot`,description:'The grid reads the `--dk-table-kit-*` copies of the design language\'s `table` slot (header height and weight, row rules, hover, selection, stripes) with its own look as every fallback: Kitora\'s language keeps the grid as it is (`table.kits: "kit"`), the other built-ins give it their table look (`"slot"`). Proof: the Kit parts section of /kits/theme/languages and `task languages:smoke`.',status:`live`},{title:`Right-to-left (RTL) layout`,description:'Set `dir="rtl"` on a wrapper (or `<html>`) and the grid mirrors: columns run right to left, cells and headers align to the inline start (`align: "end"` puts numbers on the left), `pin: "start" | "end"` stick to the inline start / end with their edge shadow and fade mirrored, column and card drop marks, tree indents, the drag handle and the resize grip sit on the logical sides, a resize drag toward the inline end widens the column, and the pager, group, tree and filter chevrons point the reading way. Built on logical classes and `rtl:` variants; the only direction read is at a resize press. The physical `left` / `right` values of `align` and `pin` keep their meaning. Demo: /kits/datagrid/rtl; tests `packages/datagrid/src/__tests__/rtl.test.tsx`.',status:`live`},{title:`Pluralization helpers`,description:'For range readouts / "N selected" / "N matching" — labels accept a function `(count: number) => string` that the caller wires to `Intl.PluralRules` (or i18n library). Removes hardcoded English plurals.',status:`planned`}]},{name:`Embed / picker`,features:[{title:"Grid as dropdown (`<DataGridPicker>`)",description:'New `<DataGridPicker value onChange triggerLabel>` — mounts a popover whose content is a fully-featured `<DataGrid>` (search / filter / sort / multi-select). Click a row → emits `onChange(rowId | rowIds)`, closes. Useful for relation pickers, "select assignee from 500 users", or any place a regular `<Combobox>` runs out of headroom (need filters / multi-column display / virt for thousands of options). Single-select OR multi-select modes; controlled OR uncontrolled. Reuses the same adapter you\'d use elsewhere — no duplicate fetch pipeline.',status:`planned`},{title:`Compact embed mode`,description:"Helper `<DataGridProvider compact>` cascades a smaller density, hides chrome (toolbar / footer / pagination by default), tightens row padding — for inline-embedded grids in detail panes, dialogs, or sidebars. Caller can re-enable specific chrome via individual feature props.",status:`planned`}]},{name:`AI tier`,features:[{title:"`<DataGridAskBar>` — natural-language filter",description:'"show me admins on Growth team active this week" → LLM returns `FilterCondition[] + SortRule[]`. Same engine, different input.',status:`planned`},{title:`AI cell value`,description:"Column meta `ai: { prompt: (row) => string }` — cell calls the LLM, caches by row id.",status:`planned`},{title:`Anomaly highlighting`,description:"Adapter optionally returns `outliers: string[]` per page; rows get a subtle warn accent.",status:`planned`},{title:`Schema explanations`,description:"Hover a column header → 1-line description from `meta.description`. Optional LLM-generated fallback.",status:`planned`}]},{name:`DX`,features:[{title:`Adapter-derived feature flags`,description:`Mirror task-list pattern: every plug-in feature auto-disables when its mutator is missing.`,status:`live`},{title:`Identity-preserving define helpers`,description:`Column ids, sort field ids, filter ids autocomplete + typecheck against caller tuples.`,status:`live`},{title:`Sandbox route`,description:"`/kits/datagrid/sandbox` — toggle every prop live. See behaviour without reading the docs.",status:`planned`},{title:`Dev-time warnings`,description:`NODE_ENV checks for column id collisions, sortFieldId mismatches, missing toWhere when filterFields supplied.`,status:`planned`},{title:`DevTools panel`,description:`Floating button → renders TableState as a JSON tree. React-Query-devtools pattern.`,status:`planned`}]}],r=e();function i(){return(0,r.jsx)(t,{intro:`Everything the datagrid kit supports today, what's mid-build, and what's explicitly planned. Use this page to scope work or confirm whether a feature ships.`,sourcePath:`src/kit/datagrid/features.ts`,groups:n})}export{i as component};